content:
{
  "root_cause": "When the drawer is opened via the Enter key, focus remains on the triggering button or the body instead of moving into the dialog, preventing keyboard users from interacting with the filter controls.",
  "repair_strategy": "Modify DialogBase._showElement to move focus to the first focusable element inside the dialog after it is shown, using SelectorEngine.find for reliable querying.",
  "edits": [
    {
      "path": "js/src/dialog-base.ts",
      "sha256": "365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b",
      "before": "  protected _showElement({ modal = true, preventBodyScroll = true }: { modal?: boolean, preventBodyScroll?: boolean } = {}): void {
    this._openedAsModal = modal

    if (modal) {
      this._element.showModal()
    } else {
      this._element.show()
    }

    if (preventBodyScroll) {
      // Lock scroll on the root element (not <body>) so it lands on the same
      // element that carries `scrollbar-gutter: stable`. Co-locating them keeps
      // the gutter reserved while the scrollbar is hidden, so the page doesn't
      // shift (and the ::backdrop covers the gutter instead of leaving a strip).
      document.documentElement.classList.add(CLASS_NAME_OPEN)
    }
  }",
      "after": "  protected _showElement({ modal = true, preventBodyScroll = true }: { modal?: boolean, preventBodyScroll?: boolean } = {}): void {
    this._openedAsModal = modal

    if (modal) {
      this._element.showModal()
    } else {
      this._element.show()
    }

    if (preventBodyScroll) {
      // Lock scroll on the root element (not <body>) so it lands on the same
      // element that carries `scrollbar-gutter: stable`. Co-locating them keeps
      // the gutter reserved while the scrollbar is hidden, so the page doesn't
      // shift (and the ::backdrop covers the gutter instead of leaving a strip).
      document.documentElement.classList.add(CLASS_NAME_OPEN)
    }

    // Move focus to the first focusable element inside the dialog
    const focusableSelectors = [
      'a[href]',
      'area[href]',
      'input:not([disabled]):not([type="hidden"])',
      'select:not([disabled])',
      'textarea:not([disabled])',
      'button:not([disabled])',
      'iframe',
      'object',
      'embed',
      '[contenteditable]',
      '[tabindex]:not([tabindex="-1"])'
    ].join(',');
    const focusable = SelectorEngine.find(focusableSelectors, this._element);
    if (focusable.length) {
      focusable[0].focus();
    }
  }"
    }
  ],
  "expected_accessibility_effect": "After opening the drawer with Enter, focus will shift to the close button (#filters-close), allowing subsequent Tab navigation to reach the In stock checkbox and other controls as expected.",
  "functional_risks": [
    "If the dialog contains no focusable elements, focus will not be moved (guarded by length check).",
    "Potential conflict with subclasses that implement custom focus management; however, none are present in this codebase."
  ],
  "verification_requirements": [
    "Pressing Enter on #filters-open results in focus on #filters-close.",
    "Subsequent Tab moves focus to #in-stock.",
    "Pressing Space toggles the checkbox.",
    "Next Tab moves focus to #apply.",
    "Pressing Enter on #apply updates the applied filter output to 'in'."
  ]
}
